
-- Table
CREATE TABLE public.vault_articles (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  category_id text NOT NULL CHECK (category_id IN ('recipes','training','recovery','mind','nervous-system')),
  slug text NOT NULL UNIQUE,
  title text NOT NULL,
  subtitle text,
  summary text NOT NULL,
  evidence_tier text NOT NULL CHECK (evidence_tier IN ('strong','promising','speculative')),
  read_time_min int NOT NULL DEFAULT 4,
  protocol jsonb NOT NULL DEFAULT '{}'::jsonb,
  benefits text[] NOT NULL DEFAULT '{}',
  risks text[] NOT NULL DEFAULT '{}',
  body_md text NOT NULL,
  references_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  display_order int NOT NULL DEFAULT 0,
  published_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX idx_vault_articles_category_order ON public.vault_articles(category_id, display_order);

ALTER TABLE public.vault_articles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Premium members can read vault articles"
  ON public.vault_articles
  FOR SELECT
  TO authenticated
  USING (public.has_premium(auth.uid()));

CREATE POLICY "No direct vault insert" ON public.vault_articles
  FOR INSERT TO authenticated WITH CHECK (false);
CREATE POLICY "No direct vault update" ON public.vault_articles
  FOR UPDATE TO authenticated USING (false);
CREATE POLICY "No direct vault delete" ON public.vault_articles
  FOR DELETE TO authenticated USING (false);

-- Seed: 20 evidence-graded articles
INSERT INTO public.vault_articles
(category_id, slug, title, subtitle, summary, evidence_tier, read_time_min, protocol, benefits, risks, body_md, references_json, display_order)
VALUES
-- ============== NUTRITION (4) ==============
('recipes','protein-1-6-2-2-g-kg',
 'Protein: 1.6–2.2 g/kg/day',
 'The non-negotiable for muscle, recovery, satiety',
 'Hitting 1.6–2.2 g of protein per kg of body weight, split across 3–4 meals, is the single highest-leverage nutrition lever for body composition, recovery, and ageing well.',
 'strong', 6,
 '{"duration":"daily","intensity":"1.6–2.2 g/kg body weight","frequency":"split across 3–4 meals, ~0.4 g/kg per meal","prerequisites":"healthy kidney function"}'::jsonb,
 ARRAY['Maximises muscle protein synthesis','Preserves lean mass during fat loss','Stronger satiety than carbs/fat (lowers spontaneous calorie intake)','Better recovery between training sessions','Slows age-related sarcopenia'],
 ARRAY['People with stage 3+ chronic kidney disease should consult a clinician','Protein cost can be a barrier — eggs, dairy, legumes are cheap anchors','Past ~2.2 g/kg shows diminishing returns'],
 E'## The dose\n\nA 2018 meta-analysis of 49 trials (Morton et al., *British Journal of Sports Medicine*) showed protein intake above **1.6 g/kg/day** maximises resistance-training-induced gains in lean mass and strength. Above ~2.2 g/kg the curve flattens.\n\nFor a 75 kg adult that''s **120–165 g/day**, ideally split into **3–4 meals of 30–45 g** to repeatedly trigger muscle protein synthesis (the ~0.4 g/kg per meal threshold from Schoenfeld & Aragon).\n\n## Why it works\n\n- **MPS pulses**: Each protein-rich meal raises muscle protein synthesis for 3–5 hours. Spreading intake captures more of these pulses than two huge meals.\n- **Leucine threshold**: ~2.5–3 g leucine per meal flips the anabolic switch. Whey, eggs, dairy, fish and lean meat clear it easily; most plant sources need a larger serving.\n- **Satiety**: Calorie-for-calorie, protein is the most filling macronutrient (Weigle et al., *Am J Clin Nutr* 2005) — people eating high-protein diets spontaneously eat ~400 fewer kcal/day.\n\n## How to apply it\n\n1. **Anchor each meal with a fist-sized portion** of meat, fish, dairy, eggs, tofu or legumes.\n2. **Hit ~30 g at breakfast** — most people front-load carbs and back-load protein, missing the morning MPS window.\n3. **Use whey or Greek yogurt** as a fast top-up if a meal falls short.\n4. **Track for 1 week**, then stop. Once you know what 30 g looks like on your plate, the count is automatic.',
 '[{"author":"Morton et al.","title":"Systematic review of protein supplementation","year":2018,"url":"https://pubmed.ncbi.nlm.nih.gov/28698222/"},{"author":"Schoenfeld & Aragon","title":"How much protein per meal","year":2018,"url":"https://pubmed.ncbi.nlm.nih.gov/29497353/"},{"author":"Weigle et al.","title":"High-protein satiety","year":2005,"url":"https://pubmed.ncbi.nlm.nih.gov/16002798/"}]'::jsonb,
 1),

('recipes','workout-fueling-stack',
 'Pre / intra / post-workout fueling',
 'Carbs around training — when, how much, why',
 'A simple three-stage fueling stack: 1–2 g/kg carbs ~2 h pre, optional 30–60 g carbs intra for sessions >75 min, and 0.3 g/kg protein + 1 g/kg carbs post.',
 'strong', 5,
 '{"duration":"around training","intensity":"pre 1–2 g/kg carbs · intra 30–60 g/h · post 0.3 g/kg protein + 1 g/kg carbs","frequency":"every training session","prerequisites":"none"}'::jsonb,
 ARRAY['Higher work output and rep quality','Faster glycogen replenishment','Better next-day session readiness','Reduced muscle protein breakdown'],
 ARRAY['Fasted training is fine for sessions <60 min','Avoid high-fibre/high-fat right before training (GI distress)','Diabetics should adjust intra-workout carbs with their clinician'],
 E'## The framework\n\nResearch from the International Society of Sports Nutrition (Kerksick et al., 2017) consolidates decades of work:\n\n- **Pre (90–180 min before)**: 1–2 g/kg of mostly carbs with ~20–40 g protein. For a 75 kg lifter that''s ~75–150 g carbs (oats + banana + Greek yogurt nails it).\n- **Intra (only if >75 min or two-a-day)**: 30–60 g carbs/hour, mixed source (glucose + fructose) to bypass single-transporter saturation.\n- **Post (within 2 h)**: ~0.3 g/kg protein (≈25 g for a 75 kg adult) + 1 g/kg carbs. Whey + rice cakes, milk + cereal, or just a normal meal — the 30-minute "anabolic window" myth is dead (Aragon & Schoenfeld, *JISSN* 2013).\n\n## What actually moves the needle\n\n1. **Carbs pre-training raise rep performance** by 3–7 % across resistance and endurance (Lambert & Flynn, 2002).\n2. **Hydration > timing**: a 2 % body-weight fluid loss tanks performance more than any timing trick.\n3. **Total daily intake matters most** — if you''re hitting protein and carb targets across the day, "missing" a perfect post-workout shake costs you nothing.\n\n## Practical defaults\n\n- Lifting fasted in AM? Coffee + 20 g whey + dextrose works.\n- Hitting the gym after work? A real lunch 3–4 h before is enough; add 30 g carbs 30 min before if energy is low.\n- Endurance >90 min? Bring 60 g carbs/hour as gels or sports drink.',
 '[{"author":"Kerksick et al.","title":"ISSN: nutrient timing","year":2017,"url":"https://pubmed.ncbi.nlm.nih.gov/28919842/"},{"author":"Aragon & Schoenfeld","title":"Nutrient timing revisited","year":2013,"url":"https://pubmed.ncbi.nlm.nih.gov/23360586/"}]'::jsonb,
 2),

('recipes','mediterranean-pattern',
 'Mediterranean eating pattern',
 'The most-evidenced longevity diet on the planet',
 'High in vegetables, legumes, fish, olive oil and whole grains; low in ultra-processed food and red meat. The PREDIMED trial cut major cardiovascular events by ~30 % over 5 years.',
 'strong', 5,
 '{"duration":"lifestyle","intensity":"≥5 servings vegetables/fruit · 2–3 servings fish/wk · ~4 tbsp extra-virgin olive oil/day · 30 g nuts/day · minimal ultra-processed food","frequency":"daily pattern, not a diet phase","prerequisites":"none"}'::jsonb,
 ARRAY['~30 % lower major cardiovascular events (PREDIMED)','Lower all-cause mortality and dementia risk','Improved insulin sensitivity and lipid profile','Compatible with most cuisines and budgets'],
 ARRAY['Olive oil is calorie-dense — measure if fat loss is the goal','Higher cost in some regions; tinned fish, beans and frozen veg fix this','Fish allergy sufferers should sub plant omega-3 sources'],
 E'## What it actually is\n\nThe Mediterranean pattern isn''t a "diet" — it''s a way of eating documented across coastal Greece, Italy, Spain and parts of North Africa. The defining traits:\n\n- **Plants are the base**: vegetables, fruit, legumes, whole grains, nuts.\n- **Fat comes from olive oil** (≈40 % of calories), not butter or seed oils.\n- **Fish 2–3×/week**, poultry and dairy in moderation, red meat rarely.\n- **Wine with meals (optional)**, never on its own.\n- **Almost no ultra-processed food.**\n\n## The evidence\n\n**PREDIMED** (Estruch et al., *NEJM* 2018, re-analysis): 7,447 high-cardiovascular-risk adults randomised to Mediterranean + extra olive oil, Mediterranean + nuts, or low-fat. Both Mediterranean arms cut **major CV events by ~30 %** over 5 years vs the low-fat control.\n\n**Lyon Diet Heart Study** (de Lorgeril, 1999): 70 % reduction in cardiac events in post-MI patients.\n\n**Cohort meta-analyses** (Sofi et al., *BMJ* 2008): each 2-point increase on the Mediterranean Adherence Score → 8 % lower all-cause mortality, 10 % lower CV mortality, 13 % lower neurodegenerative disease.\n\n## How to start\n\n1. Make **vegetables the largest item on the plate** at lunch and dinner.\n2. Default fat to **extra-virgin olive oil**.\n3. Eat **fish twice a week** (tinned sardines and salmon count).\n4. Snack on **nuts and fruit**, not packaged snacks.\n5. Cap red meat at ~1×/week.',
 '[{"author":"Estruch et al.","title":"PREDIMED","year":2018,"url":"https://www.nejm.org/doi/full/10.1056/NEJMoa1800389"},{"author":"de Lorgeril et al.","title":"Lyon Diet Heart Study","year":1999,"url":"https://pubmed.ncbi.nlm.nih.gov/9989963/"},{"author":"Sofi et al.","title":"Mediterranean diet and health","year":2008,"url":"https://www.bmj.com/content/337/bmj.a1344"}]'::jsonb,
 3),

('recipes','caffeine-timing',
 'Caffeine: dose, timing, half-life',
 '3–6 mg/kg, 45–60 min pre-effort, cut by 14:00',
 'Caffeine is the most ergogenic legal supplement on Earth — but only when dosed and timed properly. Too late and it wrecks sleep architecture for hours.',
 'strong', 4,
 '{"duration":"acute","intensity":"3–6 mg/kg body weight (≈200–400 mg adult)","frequency":"45–60 min pre-training; cut all caffeine ≥8 h before bed","prerequisites":"adult, no arrhythmia, not pregnant"}'::jsonb,
 ARRAY['~3 % improvement in endurance and strength performance (meta-analysis)','Lower perceived exertion','Sharper focus and reaction time','Cheap, well-tolerated, shelf-stable'],
 ARRAY['Half-life is 5–7 h — caffeine at 16:00 still blocks adenosine at 23:00','Tolerance builds in ~2 weeks; cycle off 1 week per quarter','Pregnant: cap at 200 mg/day','Anxiety, GERD, hypertension: tread carefully'],
 E'## Performance dose\n\nA 2020 umbrella review (Grgic et al., *Br J Sports Med*) confirmed **3–6 mg/kg of caffeine** improves both endurance and strength performance by **2–7 %**, taken **45–60 minutes before** the effort.\n\nFor a 75 kg adult: **225–450 mg** (a strong coffee = ~120 mg, a pre-workout scoop usually 200–300 mg).\n\n## Why timing matters more than people think\n\nCaffeine''s **half-life is 5–7 hours** in most adults — slower in CYP1A2 "slow metabolisers", pregnancy, and on oral contraceptives. That means:\n\n- 200 mg at 14:00 → 100 mg still in your system at 21:00.\n- Walker (2017) and others have shown 200 mg of caffeine within 6 h of bedtime cuts deep sleep by 20 %, even when subjects fall asleep "fine".\n\nRule of thumb: **last caffeine ≥ 8–10 h before target bedtime.** For most people, that''s a hard cutoff at **noon or 14:00**.\n\n## Cycling and tolerance\n\n- Tolerance to the *performance* effects builds within ~2 weeks of daily use.\n- A **1-week wash-out per quarter** (or simply skipping caffeine on rest days) preserves the ergogenic edge for hard sessions and competitions.\n\n## When to skip it\n\n- Within 90 min of high-intensity training in the evening.\n- If you''re anxious going into a big presentation — sometimes caffeine amplifies nerves more than focus.\n- If you have arrhythmia, untreated hypertension, or are pregnant — talk to a clinician first.',
 '[{"author":"Grgic et al.","title":"Caffeine and exercise performance umbrella review","year":2020,"url":"https://pubmed.ncbi.nlm.nih.gov/31613303/"},{"author":"Drake et al.","title":"Caffeine effects on sleep at 0/3/6 hours pre-bed","year":2013,"url":"https://pubmed.ncbi.nlm.nih.gov/24235903/"}]'::jsonb,
 4),

-- ============== TRAINING (4) ==============
('training','progressive-overload',
 'Progressive overload',
 'The one mechanism that drives every adaptation',
 'Force the body to do slightly more than last time — heavier load, more reps, better technique, or shorter rest. Without progression, training becomes maintenance.',
 'strong', 5,
 '{"duration":"every training week","intensity":"+2.5–5 % load when top of rep range achieved with clean technique","frequency":"weekly micro-progression, monthly macro review","prerequisites":"sound technique on the lifts being progressed"}'::jsonb,
 ARRAY['Predictable, measurable strength gains','Builds the discipline of tracking','Avoids the "treadmill of effort without progress" trap','Compounds across years'],
 ARRAY['Pushing weight before technique is dialled = injury','Joints adapt slower than muscles — increase volume gradually','Without deloads, progression eventually stalls'],
 E'## The principle\n\nProgressive overload, formalised by Selye''s **General Adaptation Syndrome** and refined in modern S&C literature, is the requirement that **training stress must rise over time** for adaptation to continue. Once a stimulus is mastered, the body stops adapting to it.\n\n## The four levers\n\nIn order of priority for a healthy lifter:\n\n1. **Load** — add 2.5–5 % when you hit the top of your rep range with crisp technique on every set.\n2. **Reps** — add a rep per set before adding weight (e.g. 5×5 → 5×6 → bump load).\n3. **Sets / volume** — once weekly hard sets per muscle exceed 8–12 (Schoenfeld''s minimum effective dose), more sets drive more growth up to ~20.\n4. **Tempo / range / density** — slower eccentrics, deeper ROM, shorter rest. Useful when load can''t go up (joint cranky, deload, travel).\n\n## How to actually program it\n\n- **Pick 2–4 main lifts** per movement pattern (squat, hinge, press, pull).\n- **Log every working set**: weight × reps × RIR (reps in reserve).\n- **Use double progression**: e.g. 4×6–8. When all sets hit 8 reps, add 2.5 kg, drop back to 6, climb again.\n- **Run a deload every 4th week** (-40 % volume) when you feel grindy or sleep tanks.\n\n## Common failure modes\n\n- Adding weight before reps are clean → form breaks, then injuries.\n- Random workouts each session ("instinctive training") → no signal, no progression.\n- Ego-loading the bar → CNS fatigue without hypertrophy stimulus.',
 '[{"author":"Schoenfeld et al.","title":"Dose-response of resistance training volume","year":2017,"url":"https://pubmed.ncbi.nlm.nih.gov/27433992/"},{"author":"Selye","title":"General Adaptation Syndrome","year":1950,"url":"https://pubmed.ncbi.nlm.nih.gov/15426442/"}]'::jsonb,
 1),

('training','zone-2-cardio',
 'Zone 2 cardio: the longevity engine',
 '180 min/week at conversational pace',
 'Sustained low-intensity aerobic work (60–70 % of max HR, where you can still hold a conversation) builds mitochondrial density, fat oxidation and cardiovascular resilience like nothing else.',
 'strong', 6,
 '{"duration":"30–60 min per session","intensity":"60–70 % HR max · talk test: full sentences possible · ~RPE 5/10","frequency":"3–4 sessions/week, 150–180 min total","prerequisites":"no acute cardiac symptoms"}'::jsonb,
 ARRAY['Increases mitochondrial number & density (Attia)','Improves fat oxidation and metabolic flexibility','Lowers resting HR and blood pressure','Major reduction in all-cause mortality (Mandsager et al.)','Zero CNS cost — stacks with strength training'],
 ARRAY['Most people train Zone 2 too hard — use HR or talk test, not feel','Time-cost is real (3–4 h/wk minimum)','New cardio? Build slowly to avoid overuse injury'],
 E'## What Zone 2 actually means\n\nIíaki San Millán''s lab (training top Tour de France riders) defines Zone 2 as the **highest intensity at which lactate stays at or below ~2 mmol/L** — i.e. mitochondria are clearing lactate as fast as they produce it.\n\nWithout a lab, two proxies work well:\n\n- **Heart rate**: 60–70 % of HR max (rough max = 208 − 0.7 × age).\n- **Talk test**: you can speak in full sentences, but a song would be a stretch.\n\nMost people sandbag this — they go too hard and end up in Zone 3 (no man''s land), or too easy (Zone 1, no real adaptation).\n\n## Why it''s the longevity engine\n\nMandsager et al. (*JAMA Network Open* 2018) followed 122,007 patients undergoing exercise stress testing. Each step up in fitness category linked to **dramatic mortality reductions** — being in the elite category was associated with **~5× lower all-cause mortality** vs the low-fitness group, comparable to or larger than the effect of stopping smoking.\n\nAttia argues VO₂max is "the single most important biomarker for lifespan" — and Zone 2 is the substrate that builds it.\n\n## The protocol\n\n- **3–4 sessions per week**, 30–60 min each.\n- **Total 150–180 min/week** is the sweet spot for a busy non-athlete.\n- **Modes that work**: brisk uphill walking, easy cycling (indoor or out), rowing, swimming, jogging if joints are happy.\n- **Stack with strength** — Zone 2 has minimal CNS impact.\n\n## Common mistakes\n\n1. Training "endurance" at HR 80 % thinking it''s Zone 2 → it''s threshold work, much more taxing.\n2. Doing 1 long session a week instead of 3–4 — the adaptation needs frequency.\n3. Skipping it because it feels too easy. The point is exactly that it feels easy.',
 '[{"author":"Mandsager et al.","title":"Cardiorespiratory fitness and long-term mortality","year":2018,"url":"https://pubmed.ncbi.nlm.nih.gov/30334239/"},{"author":"San Millán & Brooks","title":"Assessment of metabolic flexibility by means of measuring blood lactate","year":2018,"url":"https://pubmed.ncbi.nlm.nih.gov/29127602/"},{"author":"Attia","title":"Outlive","year":2023}]'::jsonb,
 2),

('training','vo2max-4x4',
 'VO₂max: the Norwegian 4×4',
 'One brutal session per week, decades of payoff',
 'Four 4-minute intervals at ~90–95 % HR max, with 3-min easy recoveries — performed 1–2× per week — produces the largest documented gains in VO₂max in the shortest time.',
 'strong', 5,
 '{"duration":"~30 min total session","intensity":"4 × 4 min @ 90–95 % HR max · 3 min active recovery between","frequency":"1–2× per week, never on consecutive days","prerequisites":"established Zone 2 base of 4–6 weeks; no acute cardiac symptoms"}'::jsonb,
 ARRAY['Largest documented VO₂max gains in trial literature (~10 % in 8 weeks)','VO₂max is one of the strongest predictors of all-cause mortality','Improves stroke volume and mitochondrial efficiency'],
 ARRAY['High CNS and cardiovascular cost — never two days in a row','Not for absolute beginners — build a Zone 2 base first','Stop immediately for chest pain, dizziness, or arrhythmia symptoms','Untreated hypertension or known cardiac disease: clear with cardiologist'],
 E'## The protocol (Helgerud et al., 2007)\n\n1. **Warm-up** 10 min easy (Zone 1–2).\n2. **4 × 4 min** at 90–95 % HR max — *hard*, you''re breathing fast and can only speak single words.\n3. **3 min active recovery** between intervals at ~70 % HR max.\n4. **Cool-down** 5 min easy.\n\nTotal session: ~30 min. Run, bike, ski-erg, row — anything that lets you push large muscle groups.\n\n## Why this dose, this format\n\nHelgerud''s landmark trial compared 4 training methods for VO₂max:\n\n- Long slow distance\n- Lactate threshold work\n- 15/15 short intervals\n- **4×4 long intervals** ← winner\n\nThe 4×4 group gained **~10 % in VO₂max over 8 weeks**, double the slow-distance group, with the same total energy expenditure.\n\nVO₂max correlates with **all-cause mortality more strongly than smoking, hypertension or diabetes** (Mandsager 2018) — improving it is one of the highest-leverage things a healthy adult can do.\n\n## How to integrate it\n\n- **Build a Zone 2 base for 4–6 weeks** before adding 4×4. Without it, the intervals feel impossible and recovery suffers.\n- **1×/week** if you also lift heavy 3×/week. **2×/week** if you''re cardio-focused.\n- **Place it on a non-leg-heavy lifting day**, ideally with 24+ h before/after the next hard session.\n- **Track**: split times, average HR, RPE. You should see splits hold or improve as fitness builds.\n\n## When to back off\n\nIf morning HR is elevated 5+ bpm for 3 days, or sleep tanks, swap the 4×4 for an easy Zone 2 session. The interval work is potent — and potency cuts both ways.',
 '[{"author":"Helgerud et al.","title":"Aerobic high-intensity intervals improve VO2max more than moderate training","year":2007,"url":"https://pubmed.ncbi.nlm.nih.gov/17414804/"},{"author":"Mandsager et al.","title":"Cardiorespiratory fitness and long-term mortality","year":2018,"url":"https://pubmed.ncbi.nlm.nih.gov/30334239/"}]'::jsonb,
 3),

('training','deload-periodization',
 'Deload weeks: the missing piece',
 'Why every 4th week should be lighter',
 'Planned reductions in volume (–40 %) every 4–6 weeks let connective tissue, the CNS and motivation catch up with muscular adaptation, allowing the next training block to start fresh.',
 'promising', 4,
 '{"duration":"1 week","intensity":"reduce volume ~40 % (sets), keep load 75–85 % of working weights","frequency":"every 4th week, or when 3+ accumulating fatigue markers appear","prerequisites":"hard training block of 3+ weeks"}'::jsonb,
 ARRAY['Restores joint and connective tissue resilience','Returns CNS to baseline (sleep, mood, focus rebound)','Often produces a small PR upon return','Reduces overuse injury risk'],
 ARRAY['Skipping deloads doesn''t make you tougher — it accumulates','Going too light defeats the purpose: keep load near working weight','New lifters can usually push 6 weeks before needing one'],
 E'## The principle\n\nProgress is **stress + recovery**, not just stress. Israetel and others have argued (and the strength literature shows) that planned **recovery weeks let the slowest-adapting tissues catch up**:\n\n- Muscle adapts in days.\n- CNS recovers in days, but accumulates fatigue across weeks.\n- **Tendons and joint capsules adapt in months.**\n\nIf you train hard for 12 weeks straight, your muscles are ready for more — but your knees, elbows and central drive often aren''t.\n\n## The protocol\n\n- **Cut sets by ~40 %** (e.g. 12 working sets/muscle/week → 7).\n- **Keep load 75–85 %** of your usual working weight — heavy enough to feel "real", light enough to recover.\n- **Drop intensity techniques**: no failure work, no AMRAP sets, no drop sets.\n- **Run for one week**, then jump back into the next training block.\n\n## How to time it\n\nTwo viable patterns:\n\n1. **Fixed**: every 4th week is a deload. Predictable, easy to plan around travel.\n2. **Auto-regulated**: deload when ≥3 of these stack up:\n   - Sleep degraded for 3+ nights\n   - Resting HR up 5+ bpm\n   - Mood/motivation drop\n   - Joint pain in lifts that were fine 2 weeks ago\n   - Bar speed decreasing at the same load\n\n## What deloads are NOT\n\n- A week off the gym (you lose the movement pattern groove).\n- A week of "different" workouts (random circuits = same total stress).\n- A diet break (separate variable — manage independently).',
 '[{"author":"Israetel et al.","title":"Scientific Principles of Hypertrophy Training","year":2021},{"author":"Bell et al.","title":"Recovery from heavy resistance exercise","year":2020,"url":"https://pubmed.ncbi.nlm.nih.gov/32568822/"}]'::jsonb,
 4),

-- ============== RECOVERY & SLEEP (4) ==============
('recovery','sleep-7-9-hours',
 'Sleep: 7–9 hours, every night',
 'The closest thing to a master health lever',
 'Adults sleeping <7 h/night for 14+ days perform like the legally drunk on cognitive tests, while showing measurable hits to immune function, glucose tolerance, hormones and cardiovascular risk.',
 'strong', 6,
 '{"duration":"7–9 h nightly","intensity":"consistent ±30 min bedtime/wake-time","frequency":"every night, including weekends","prerequisites":"none"}'::jsonb,
 ARRAY['Memory consolidation and learning','Glucose tolerance and insulin sensitivity','Testosterone, growth hormone, leptin/ghrelin balance','Immune function (vaccine response 2× higher in 7+ h sleepers)','Lower 10-year cardiovascular and Alzheimer risk'],
 ARRAY['Sleep is highly individual — measure your own response, not the average','Shift workers face structural challenges; this protocol assumes a normal schedule','Severe insomnia warrants CBT-I, not willpower'],
 E'## The dose\n\nThe American Academy of Sleep Medicine and Sleep Research Society jointly recommend **≥7 h per night for adults** (Watson et al., *Sleep* 2015). The upper end (~9 h) is also fine — only consistently >10 h or <6 h is associated with worse outcomes.\n\n**Consistency matters as much as duration.** Going to bed at the same time ±30 min anchors your circadian rhythm; "social jet lag" on weekends has been linked to metabolic syndrome (Wittmann et al., 2006).\n\n## Why short sleep is a tax on everything\n\n- **Cognition**: Van Dongen et al. (2003) showed 6 h/night for 14 days caused performance decrements equivalent to a blood alcohol of 0.08 % — and subjects had no idea.\n- **Glucose**: One week of 5 h sleep cuts insulin sensitivity by ~25 % in healthy young adults (Buxton et al., 2010).\n- **Hormones**: 1 week of 5 h sleep drops testosterone by 10–15 % (Leproult & Van Cauter, 2011).\n- **Immunity**: People sleeping <7 h are nearly **3× more likely to catch a cold** than 8 h sleepers (Prather et al., 2015).\n\n## The 7-rule sleep stack\n\n1. **Anchor wake time** — same time daily, even weekends.\n2. **Morning light** — 10 min outside within 60 min of waking.\n3. **Caffeine cut-off** — 8–10 h before bed.\n4. **Last big meal** 2–3 h before bed.\n5. **Cool, dark, quiet** — 17–19 °C, blackout, ear plugs if needed.\n6. **Wind-down ritual** — same 30-min sequence so your brain learns the cue.\n7. **Phone out of the bedroom** — yes, really.\n\nIf you only do one thing: **fix wake time.** Bedtime follows.',
 '[{"author":"Watson et al.","title":"Joint AASM/SRS sleep duration recommendations","year":2015,"url":"https://pubmed.ncbi.nlm.nih.gov/26039963/"},{"author":"Van Dongen et al.","title":"Cumulative cost of additional wakefulness","year":2003,"url":"https://pubmed.ncbi.nlm.nih.gov/12683469/"},{"author":"Walker","title":"Why We Sleep","year":2017}]'::jsonb,
 1),

('recovery','morning-light-anchor',
 'Morning light: 10 minutes outside',
 'The single biggest circadian lever',
 'Bright outdoor light within 60 minutes of waking sets your circadian rhythm, advances melatonin onset that evening, and reliably improves mood, alertness and sleep onset latency.',
 'strong', 4,
 '{"duration":"10 min on bright/sunny days · 20 min on overcast · 30 min if heavy cloud","intensity":"outdoor light only — windows block ~50 % of the relevant wavelengths","frequency":"daily, every day, year round","prerequisites":"none"}'::jsonb,
 ARRAY['Anchors circadian rhythm — better sleep onset that evening','Sharp alertness boost via morning cortisol pulse','Reduces depression scores in seasonal and non-seasonal mood issues','Improves daytime focus and energy'],
 ARRAY['Never look directly at the sun','In high-UV regions, get the light early before peak UV','Sunglasses defeat the protocol — clear glasses or contacts are fine'],
 E'## Why morning light\n\nIntrinsically photosensitive retinal ganglion cells (ipRGCs) — discovered by Berson et al. in 2002 — sit in your retina and signal directly to the suprachiasmatic nucleus, your master circadian clock. They''re tuned to **bright, blue-rich light**, which means:\n\n- **Outdoor light at 7:00 AM**: 10,000–100,000 lux\n- **Bright office light**: 300–500 lux\n- **Through a window**: ~50 % of the outdoor signal\n\nThe ipRGCs need **photons through the eye, not the skin**. Sunglasses block them; closed eyes block them. Just being outside, eyes open, naturally looking around, is enough.\n\n## What it does (immediately)\n\n- **Boosts morning cortisol pulse** — the healthy kind, sharpens alertness and mood for hours.\n- **Sets the timer for melatonin** to rise ~14–16 h later, so sleep comes more easily that night.\n- **Suppresses lingering melatonin** that''s still circulating from the night.\n\n## What it does (long term)\n\nA 2022 UK Biobank analysis (Burns et al., *J Affect Disord*) on 86,000 adults: those getting more daylight averaged **lower depression scores, better self-reported sleep, and higher daytime energy**. The effect was dose-responsive.\n\n## The minimum effective dose\n\n- **Sunny day**: 5–10 min.\n- **Cloudy/overcast**: 15–20 min.\n- **Heavy cloud / pre-dawn / winter**: 30 min, or use a 10,000-lux SAD lamp at desk distance for 20–30 min.\n\nMake it the first thing after waking — paired with coffee, a dog walk, or a 5-min walk to get a real breakfast. The compounding sleep and mood benefits over months and years are massive.',
 '[{"author":"Berson et al.","title":"Phototransduction by retinal ganglion cells","year":2002,"url":"https://pubmed.ncbi.nlm.nih.gov/11834834/"},{"author":"Burns et al.","title":"Time spent in daylight and mental health","year":2022,"url":"https://pubmed.ncbi.nlm.nih.gov/36116595/"},{"author":"Huberman Lab podcast","title":"Sleep Toolkit","year":2022}]'::jsonb,
 2),

('recovery','caffeine-cutoff',
 'The caffeine sleep cut-off',
 'Why your 16:00 coffee is wrecking deep sleep',
 'Caffeine has a 5–7 h half-life — meaning a 200 mg coffee at 16:00 still leaves 100 mg blocking adenosine receptors at midnight. Most people who "sleep fine on caffeine" simply don''t know what real sleep feels like.',
 'strong', 4,
 '{"duration":"daily","intensity":"all caffeine sources (coffee, tea, pre-workout, dark chocolate, some sodas)","frequency":"hard cut-off ≥8–10 h before target bedtime","prerequisites":"none"}'::jsonb,
 ARRAY['~20 % more deep sleep within 1 week','Easier sleep onset','Better next-morning alertness without caffeine dependency','Restored caffeine sensitivity over time'],
 ARRAY['Headaches/fatigue for 2–4 days as adenosine system recalibrates','Slow CYP1A2 metabolisers may need an even earlier cut-off','Decaf still has ~5–10 mg caffeine — fine, but counts'],
 E'## The chemistry\n\nCaffeine works by **blocking adenosine receptors** — adenosine is the molecule that builds up across the day creating "sleep pressure". Block it, and tiredness disappears. Stop blocking it, and the accumulated pressure crashes back.\n\n**Half-life**: 5–7 hours in most adults. That means:\n\n| Time | 200 mg consumed at 09:00 | 200 mg consumed at 16:00 |\n|---|---|---|\n| Bedtime 23:00 | ~25 mg active | ~100 mg active |\n\n100 mg at bedtime is **enough to measurably degrade deep sleep**, even when you fall asleep on time. Drake et al. (2013) showed 400 mg taken 0, 3 or 6 hours pre-bed all reduced sleep duration and quality vs placebo, with the 6-h dose having a clearly measurable effect.\n\n## The dose-response on sleep\n\nA classic Walker & Stickgold finding: people consuming caffeine within 6 h of bed lose **~20 % of their slow-wave sleep** — without realising it. Slow-wave sleep is when your brain clears beta-amyloid (relevant to long-term Alzheimer risk) and your body releases growth hormone.\n\n## The protocol\n\n- **Bedtime 23:00 → last caffeine 14:00.**\n- **Bedtime 22:00 → last caffeine 13:00.**\n- Includes pre-workout, green tea, matcha, dark chocolate, and most "natural energy" drinks.\n\nIf you can''t make it through the afternoon, the issue is usually **sleep debt or post-lunch glucose dip**, not "needing" coffee. A 10-min walk or a small protein snack handles both.\n\n## Two-week test\n\nCut caffeine after 14:00 for 14 days. Most people report:\n- Falling asleep faster within ~5 days\n- Deeper sleep / fewer night wake-ups within ~7 days\n- Higher *natural* morning energy within 10–14 days',
 '[{"author":"Drake et al.","title":"Caffeine effects on sleep at 0/3/6 hours pre-bed","year":2013,"url":"https://pubmed.ncbi.nlm.nih.gov/24235903/"},{"author":"Walker","title":"Why We Sleep","year":2017},{"author":"Clark & Landolt","title":"Coffee, caffeine and sleep","year":2017,"url":"https://pubmed.ncbi.nlm.nih.gov/27612937/"}]'::jsonb,
 3),

('recovery','cold-exposure',
 'Cold exposure: dose, timing, who',
 '2–3 minutes ≤15 °C, kept away from strength sessions',
 'Brief cold immersion reliably boosts mood, alertness and dopamine, and may improve insulin sensitivity — but blunts strength and hypertrophy gains if used within 6 hours of resistance training.',
 'promising', 5,
 '{"duration":"2–3 min total per session","intensity":"≤15 °C water immersion or cold shower","frequency":"2–4× per week, ≥6 h after strength training, never within 4 h of bed","prerequisites":"healthy cardiovascular system; not pregnant; no Raynaud''s"}'::jsonb,
 ARRAY['Sharp dopamine spike (~250 % over baseline) — durable mood boost','Increased alertness via norepinephrine release','Possible improvements in insulin sensitivity and brown fat activity','Builds the discipline of doing hard things on demand'],
 ARRAY['Blunts hypertrophy and strength when used within ~6 h of resistance training','Avoid in late evening — too activating for sleep','Cardiovascular conditions, pregnancy, Raynaud''s: clear with clinician','Never alone in open water'],
 E'## What the dose actually is\n\nThe most-cited number — popularised by Søberg et al. (2021) — is **~11 minutes per week of total cold exposure**, broken into 2–4 sessions.\n\nA practical structure:\n\n- **3 × 3 min sessions per week**, or\n- **4 × ~2.5 min sessions per week**.\n\nWater (or shower) temperature: **uncomfortably cold** — generally ≤15 °C (≤59 °F). The body can''t cheat at this temperature; you''re cold whether you breathe through it or not.\n\n## The dopamine effect\n\nŠrámek et al. (2000) measured a **~250 % rise in dopamine** in subjects after cold immersion (14 °C, 1 h). Unlike the dopamine crash you get from short-acting stimulants, the cold-induced rise stays elevated for hours.\n\nThis maps onto the lived experience: a few minutes of cold reliably produces hours of clean alertness and mood lift, with no rebound crash.\n\n## When NOT to use it\n\n**Within 6 hours after strength or hypertrophy training.** Multiple trials (e.g. Roberts et al., 2015; Fyfe et al., 2019) show post-lift cold immersion **blunts long-term strength and muscle growth gains by ~10–25 %** by suppressing the inflammatory signal that drives adaptation.\n\nIf strength is a primary goal: do cold on rest days or before training, not after.\n\n## Practical protocol\n\n1. **End your morning shower with 60–180 s cold.** Build week by week.\n2. **Box-breathe through the gasp reflex** (4-4-4-4) for the first 30 seconds.\n3. **Stop when finished — no need to "tough it out" longer than 3 min.** Diminishing returns and increasing risk past that point for non-acclimatised users.\n4. **Re-warm passively** (towel, dry clothes, movement). Avoid jumping straight into a hot shower if possible — the rebound vasodilation is part of the adaptation.',
 '[{"author":"Søberg et al.","title":"Cold exposure and brown fat / metabolism","year":2021,"url":"https://pubmed.ncbi.nlm.nih.gov/34555340/"},{"author":"Šrámek et al.","title":"Human physiological responses to immersion in cold water","year":2000,"url":"https://pubmed.ncbi.nlm.nih.gov/10751106/"},{"author":"Roberts et al.","title":"Post-exercise cold water immersion attenuates training adaptations","year":2015,"url":"https://pubmed.ncbi.nlm.nih.gov/26174323/"}]'::jsonb,
 4),

-- ============== MIND (4) ==============
('mind','box-breathing',
 'Box breathing for acute stress',
 '4-4-4-4 — the Navy SEALs'' down-regulator',
 'Equal-count breathing (4 in / 4 hold / 4 out / 4 hold) for 5 minutes activates the parasympathetic nervous system, lowers heart rate, and resets focus. It works in 60 seconds; full effect in 5.',
 'strong', 3,
 '{"duration":"5 min (or 1 min minimum)","intensity":"4-4-4-4 cadence, nose breathing","frequency":"on demand for stress, anxiety, before high-pressure moments","prerequisites":"none"}'::jsonb,
 ARRAY['Acute drop in heart rate and blood pressure','Lower self-reported anxiety within 5 min','Improved focus and decision quality after','Free, silent, deployable anywhere'],
 ARRAY['Pregnancy, severe respiratory conditions: shorten holds','Don''t do while driving (deep relaxation can affect alertness)','Light-headedness on first attempts is normal — slow down'],
 E'## The pattern\n\n```\n   inhale 4s\n      ┌──────┐\n      │      │\nhold  │      │ hold\n4s    │      │ 4s\n      │      │\n      └──────┘\n   exhale 4s\n```\n\nNose-breathe through the inhale and exhale. Hold gently — no straining.\n\n## Why it works\n\nBox breathing exploits two physiological levers:\n\n1. **Vagal activation via long, slow exhalation** — exhaling longer than (or equal to) the inhale shifts the autonomic balance toward parasympathetic dominance (Russo et al., *Breathe* 2017).\n2. **CO₂ tolerance** — the holds slightly raise blood CO₂, which over time recalibrates the respiratory chemoreceptors and reduces baseline anxiety reactivity.\n\nThis is the same pattern taught at US Navy SEAL BUD/S to manage performance anxiety in the water.\n\n## Where to use it\n\n- **Before a presentation, hard conversation, or high-stakes call** (5 min).\n- **In traffic / when angry** (1–2 min).\n- **As a 5-min wind-down before sleep** (lengthen exhale to 6 s).\n- **Between intense training sets** when your HR is racing and you need to focus.\n\n## A 5-minute starter session\n\n1. Sit upright, eyes soft or closed.\n2. Exhale fully to start.\n3. Inhale through nose for 4 s.\n4. Hold for 4 s — gentle, no clenching.\n5. Exhale through nose for 4 s.\n6. Hold for 4 s.\n7. Repeat for 5 minutes (~18–20 cycles).\n\nIf 4-4-4-4 feels rushed, drop to 3-3-3-3. If too easy, build to 5-5-5-5 or 6-6-6-6.',
 '[{"author":"Russo et al.","title":"The physiological effects of slow breathing","year":2017,"url":"https://pubmed.ncbi.nlm.nih.gov/29209423/"},{"author":"Divine","title":"The Way of the SEAL","year":2013}]'::jsonb,
 1),

('mind','physiological-sigh',
 'The physiological sigh',
 'Stanford''s 60-second stress kill switch',
 'Two short inhales through the nose followed by one long exhale through the mouth — repeated for 1–3 minutes — was the single most effective breath pattern for reducing stress in a 2023 Stanford trial.',
 'strong', 3,
 '{"duration":"1–5 min","intensity":"double nasal inhale + extended mouth exhale, repeated","frequency":"on demand for acute stress, anxiety spikes","prerequisites":"none"}'::jsonb,
 ARRAY['Largest measured drop in self-reported anxiety vs other breath patterns (Balban 2023)','Fast acting (effects in <60 s)','Improves mood for hours after a 5-min daily practice'],
 ARRAY['Light-headedness if done lying down too vigorously','Less effective if rushed — the long exhale is the active ingredient'],
 E'## How to do it\n\n1. **Inhale through your nose** to about 70 % full.\n2. **Top up with a second short nasal inhale** (a quick "sip" on top of the first breath).\n3. **Exhale slowly through pursed lips** until the lungs are fully empty (target: 8–10 s).\n4. Repeat for 1–5 minutes.\n\n## Why two inhales\n\nThe second inhale **re-inflates collapsed alveoli** in the lungs, allowing more efficient CO₂ offload on the long exhale. CO₂ offload is the strongest acute lever for shifting from sympathetic ("fight or flight") to parasympathetic ("rest and digest") tone.\n\nThe sigh is something humans (and dogs, cats, mice) do spontaneously every few minutes — typically when stress, sleep onset or relaxation is needed. It''s pre-wired.\n\n## The Stanford trial\n\nBalban et al. (*Cell Reports Medicine*, 2023) randomised 108 healthy adults to:\n\n- **Cyclic sighing** (the protocol above)\n- **Box breathing**\n- **Cyclic hyperventilation** (Wim Hof-style)\n- **Mindfulness meditation**\n\nAll for **5 min/day for 28 days.**\n\nResult: **cyclic sighing produced the largest reduction in self-reported anxiety and the largest improvement in positive mood.** Mindfulness was effective but slower.\n\n## When to use it\n\n- **Acute stress spike** — 60 s often enough.\n- **Pre-sleep wind-down** — 2–3 min in bed.\n- **Between meetings as a reset** — far more reliable than scrolling.\n- **Before a difficult conversation** — restores calm without sedation.',
 '[{"author":"Balban et al.","title":"Brief structured respiration practices enhance mood and reduce physiological arousal","year":2023,"url":"https://pubmed.ncbi.nlm.nih.gov/36630953/"},{"author":"Vlemincx et al.","title":"Sighs as resetters of physiological state","year":2010,"url":"https://pubmed.ncbi.nlm.nih.gov/20382180/"}]'::jsonb,
 2),

('mind','mindfulness-mbsr',
 'Mindfulness: 10 minutes a day',
 'MBSR-style daily practice — small dose, large signal',
 '10 minutes of formal mindfulness practice per day for 8 weeks produces measurable changes in attention, emotional regulation, and stress reactivity — comparable in effect size to common SSRIs for mild-to-moderate anxiety.',
 'strong', 5,
 '{"duration":"10 min/day to start (target: 20 min)","intensity":"breath-anchored awareness; return attention without judgment when it wanders","frequency":"daily, ideally same time","prerequisites":"none — but trauma history may benefit from a guided/clinical program"}'::jsonb,
 ARRAY['Reduced anxiety and depression scores comparable to SSRIs in mild-moderate cases (Hoge 2023)','Improved attention control and working memory','Lower stress reactivity (cortisol) over weeks','Compounding benefit — 8 weeks shows structural brain change'],
 ARRAY['Trauma sufferers may experience flooding — a trauma-informed teacher or program is safer','Boredom and resistance in week 1–2 are normal','Apps help, but a teacher-led MBSR course outperforms apps for severe cases'],
 E'## The minimum dose\n\nKabat-Zinn''s **Mindfulness-Based Stress Reduction (MBSR)** program — the most-studied secular mindfulness curriculum — is 8 weeks of daily 30–45 min practice. But:\n\n- A 2014 JAMA meta-analysis (Goyal et al.) found **moderate evidence for ~8 weeks of even briefer practice** improving anxiety, depression and pain.\n- Hoge et al. (*JAMA Psychiatry* 2023) directly compared **8 weeks of MBSR to escitalopram (Lexapro)** for anxiety disorders. **Outcomes were equivalent.**\n\nIn practice: **10 min/day, every day, for 8 weeks** is the realistic starter dose for a busy adult.\n\n## The practice (basic breath anchor)\n\n1. Sit upright. Eyes closed or soft gaze down.\n2. Bring attention to the breath — at the nostrils, chest, or belly.\n3. Notice each inhale and exhale, without trying to change them.\n4. **When attention wanders** (and it will, dozens of times) — notice "thinking", and gently return to the breath. *That return is the rep.* Each one is the equivalent of a bicep curl for your prefrontal cortex.\n5. Continue for 10 min. End by taking one deeper breath.\n\n## What it actually does (long-term)\n\n- **Attention**: Stronger top-down control, less mind-wandering (Mrazek et al., 2013).\n- **Emotional regulation**: Lower amygdala reactivity to negative stimuli (Goldin et al., 2010).\n- **Stress hormones**: Reduced cortisol response to acute stressors (Pascoe et al., 2017 meta-analysis).\n- **Brain structure**: After 8 weeks, increased grey matter density in hippocampus, decreased in amygdala (Hölzel et al., 2011).\n\n## How to actually do it for 8 weeks\n\n- **Same time, same chair** — habit stack with morning coffee or pre-bed.\n- **Use a guided app** (Waking Up, Insight Timer, 10 % Happier) if a teacher isn''t accessible.\n- **Skip-day rule**: never skip two days in a row.\n- **Don''t evaluate sessions** — most "bad" sessions are doing the work.',
 '[{"author":"Hoge et al.","title":"MBSR vs escitalopram for anxiety disorders","year":2023,"url":"https://pubmed.ncbi.nlm.nih.gov/36350593/"},{"author":"Goyal et al.","title":"Meditation programs for psychological stress","year":2014,"url":"https://pubmed.ncbi.nlm.nih.gov/24395196/"},{"author":"Hölzel et al.","title":"Mindfulness practice leads to increases in regional brain grey matter","year":2011,"url":"https://pubmed.ncbi.nlm.nih.gov/21071182/"}]'::jsonb,
 3),

('mind','cognitive-reframing',
 'Cognitive reframing (CBT)',
 'The thought-checking habit that quietly rewires you',
 'Catching automatic negative thoughts, naming the cognitive distortion, and rewriting them in evidence-based form is the engine behind CBT — the most-evidenced talk therapy on the planet.',
 'strong', 6,
 '{"duration":"5–10 min when triggered","intensity":"3-column journal: situation → automatic thought → reframe","frequency":"on demand, daily during high-stress periods","prerequisites":"none — but severe depression/PTSD: pair with a therapist"}'::jsonb,
 ARRAY['Reduces depression/anxiety symptoms across hundreds of trials','Effects equal or exceed SSRIs for many conditions, with longer-lasting benefit','Builds metacognitive awareness — you stop *being* your thoughts','Free, learnable from books and apps'],
 ARRAY['Severe depression: do this with a therapist, not alone','Reframing isn''t "positive thinking" — it requires honest evidence','Skip when emotionally flooded; come back when calmer'],
 E'## The premise\n\nDeveloped by Aaron Beck in the 1960s and refined by David Burns, **Cognitive Behavioural Therapy (CBT)** rests on one observation: *thoughts cause feelings, not events*. Two people in the same situation will feel very different things based on what they tell themselves about it.\n\nMost emotional suffering follows a small number of **cognitive distortions**: catastrophising, all-or-nothing thinking, mind-reading, personalising, "should" statements, etc.\n\n## The 3-column tool\n\n| Situation | Automatic thought | Reframe |\n|---|---|---|\n| Sent a message, no reply in 4 h | "She''s pissed at me" *(mind-reading, catastrophising)* | "She''s probably busy. Last time this happened she replied that evening. I''ll wait until tonight." |\n| Missed a workout | "I''m back to square one" *(all-or-nothing)* | "One missed session inside 20 last month is noise, not a trend. I''ll lift tomorrow." |\n| Got critical feedback at work | "My boss thinks I''m bad at my job" *(jumping to conclusions)* | "He pointed out one specific thing. He praised two others. The criticism is actionable." |\n\n## The protocol\n\n1. **Catch the feeling first** (anger, anxiety, shame).\n2. **Write the situation** — facts only, no interpretation.\n3. **Write the automatic thought** verbatim, even if it''s ugly.\n4. **Name the distortion** (catastrophising, etc.).\n5. **Write the reframe** — what would you tell a smart friend in this situation? Use *evidence*, not affirmations.\n\nDo this **5–10 times when triggered**, daily during stressful periods. After ~4 weeks, the catch-and-reframe starts happening in real time.\n\n## The evidence base\n\n- Hofmann et al. (*Cogn Ther Res*, 2012) meta-analysed **269 CBT trials**: large effect sizes for anxiety disorders, depression, OCD, PTSD, eating disorders.\n- DeRubeis et al. (2005): CBT was **as effective as antidepressants** at 16 weeks, with **lower relapse** at follow-up.\n- Cuijpers et al. (2023): the effects hold up across cultures, age groups, and severity levels.\n\n**Best free resource**: David Burns'' *Feeling Good* (book) — the entire CBT toolkit in lay language.',
 '[{"author":"Hofmann et al.","title":"The efficacy of CBT: a review of meta-analyses","year":2012,"url":"https://pubmed.ncbi.nlm.nih.gov/23459093/"},{"author":"Hoge et al.","title":"MBSR vs escitalopram","year":2023,"url":"https://pubmed.ncbi.nlm.nih.gov/36350593/"},{"author":"Burns","title":"Feeling Good","year":1980}]'::jsonb,
 4),

-- ============== NERVOUS SYSTEM (4) ==============
('nervous-system','polyvagal-fundamentals',
 'Polyvagal theory: the basics',
 'Why "calm down" doesn''t work — and what does',
 'Stephen Porges'' polyvagal model maps three nervous-system states (ventral vagal safety, sympathetic mobilisation, dorsal vagal shutdown) and gives you concrete levers — humming, cold face, slow exhalation — to shift between them.',
 'promising', 6,
 '{"duration":"reading + 5–10 min daily practice","intensity":"identify state → apply matching tool (humming, gargling, slow exhale, cold face)","frequency":"daily; on-demand when dysregulated","prerequisites":"none — trauma history: do with trauma-informed practitioner"}'::jsonb,
 ARRAY['Language to identify nervous system state in real time','Tool selection matches the state (no more "calm down" advice that fails)','Improves co-regulation in relationships','Highly compatible with therapy work'],
 ARRAY['Polyvagal theory''s neuroanatomy is debated in some specialist circles — the *practical tools* still work','Trauma-informed framing is essential when working with PTSD','Not a replacement for clinical care'],
 E'## The three states\n\nPolyvagal theory (Porges, 1995, 2011) maps the autonomic nervous system into three hierarchical states:\n\n| State | Feels like | Bodily signals |\n|---|---|---|\n| **Ventral vagal (safety)** | Connected, curious, present, playful | Steady HR, eye contact easy, voice prosody |\n| **Sympathetic (mobilised)** | Anxious, angry, racing, "wired" | Fast HR, shallow breath, narrow vision |\n| **Dorsal vagal (shutdown)** | Numb, disconnected, foggy, "checked out" | Low HR, low energy, dissociation |\n\nThe states are **hierarchical**: from shutdown you must pass through sympathetic activation to reach safety. Trying to "calm down" from full mobilisation by going limp doesn''t work — your body needs to discharge first.\n\n## Why this matters in practice\n\nMost stress advice ("just relax", "take a deep breath") assumes you''re already in ventral vagal and just need a top-up. If you''re in sympathetic mobilisation, telling yourself to relax often *increases* arousal. The polyvagal frame gives you state-matched tools.\n\n## The toolkit by state\n\n**If sympathetic (anxious, angry, racing):**\n- Long exhalation breathing (5-5-5-5 or extended exhale 4-in / 8-out)\n- Cold water on the face — activates the mammalian dive reflex (see separate article)\n- Slow voo / humming — vagus nerve runs through the throat\n- Movement to discharge: walk, shake, push against a wall\n\n**If dorsal vagal (numb, frozen):**\n- Don''t try to "relax" — gently mobilise first\n- Brief light movement: walking, easy bouncing\n- Cold splash + quick movement\n- Then transition to ventral tools\n\n**To stay in ventral (the goal):**\n- Co-regulation with safe people (eye contact, slow conversation)\n- Singing, humming, playing music\n- Gentle Zone 2 movement\n- Time outdoors\n\n## A daily 5-min ventral practice\n\n1. **Long exhale breathing** — 2 min (4 in / 8 out).\n2. **Humming "voo"** on each exhale — 1 min.\n3. **Soft eye gaze** at something pleasant or person''s face — 2 min.\n\nDo this daily for 4 weeks. The body learns the route.',
 '[{"author":"Porges","title":"The Polyvagal Theory","year":2011},{"author":"Dana","title":"The Polyvagal Theory in Therapy","year":2018},{"author":"Gerritsen & Band","title":"Breath of Life: respiratory vagal stimulation","year":2018,"url":"https://pubmed.ncbi.nlm.nih.gov/30356789/"}]'::jsonb,
 1),

('nervous-system','nsdr-yoga-nidra',
 'NSDR / Yoga Nidra',
 'A 10-minute "deposit" against sleep debt',
 'Non-Sleep Deep Rest — guided body-scan protocols rooted in Yoga Nidra — measurably restores dopamine, lowers cortisol, and improves daytime alertness with as little as 10 minutes of practice.',
 'promising', 4,
 '{"duration":"10–20 min","intensity":"lying down, eyes closed, follow guided audio","frequency":"daily or 3–4×/week; particularly after a poor night''s sleep","prerequisites":"a quiet room and a guided track"}'::jsonb,
 ARRAY['Restores energy after a poor night''s sleep','~65 % increase in striatal dopamine in one PET study (Kjaer 2002)','Lowers cortisol and blood pressure acutely','Improves attention and learning consolidation'],
 ARRAY['Some people fall fully asleep — fine, but set an alarm if needed','Lying flat is uncomfortable for some — bend knees or use a bolster','Trauma-sensitive: choose a teacher with appropriate training'],
 E'## What it is\n\nNSDR (a term popularised by Andrew Huberman) is the secular umbrella for **Yoga Nidra-style guided body scans** that walk you through systematic relaxation while staying in a hypnagogic, semi-aware state.\n\nA typical 15-minute session:\n\n1. **Lie flat**, eyes closed.\n2. **Body scan** — attention moves slowly from feet to head, releasing tension at each region.\n3. **Breath awareness** — long, slow nasal breathing.\n4. **Visualisation or rest** — depending on the tradition.\n5. **Gentle re-orientation** — small movements, then sit up.\n\n## Why it works\n\n**Kjaer et al. (2002)** scanned brains of experienced meditators during Yoga Nidra and observed a **~65 % increase in dopamine release** in the striatum — comparable to taking a low-dose stimulant. Dopamine in this region governs motivation and willingness to act.\n\n**Datta et al. (2017, 2021)**: 8 weeks of Yoga Nidra in students reduced anxiety and improved sleep quality vs control.\n\n**Mechanistically**: NSDR shifts you into a **theta-dominant brain state** (similar to early sleep stages) without falling asleep. This state appears to consolidate motor and declarative learning, restore attention, and lower sympathetic tone.\n\n## When to use it\n\n- **After a bad night''s sleep** — 20 min around midday is the closest thing to a "make-up deposit" we have.\n- **Mid-afternoon dip** — alternative to caffeine after 14:00.\n- **Pre-creative work** — clears mental clutter before deep focus.\n- **Wind-down before bed** — though it can be too activating for some.\n\n## How to actually start\n\n- Search "NSDR" or "Yoga Nidra" on YouTube/Spotify (free Huberman, Liam Gillen, Ally Boothroyd tracks).\n- **Lie flat or recline.** Knees bent if back hurts.\n- **No headphones is fine** — speakers work.\n- **Don''t try to "do it right"**. Even falling asleep some sessions is fine.\n- **Start with 10 min.** Build to 20 if it serves you.',
 '[{"author":"Kjaer et al.","title":"Increased dopamine tone during meditation-induced change of consciousness","year":2002,"url":"https://pubmed.ncbi.nlm.nih.gov/11958969/"},{"author":"Datta et al.","title":"Yoga Nidra and sleep quality","year":2021,"url":"https://pubmed.ncbi.nlm.nih.gov/34390388/"},{"author":"Huberman Lab podcast","title":"NSDR Toolkit","year":2022}]'::jsonb,
 2),

('nervous-system','coherent-breathing-5-5',
 'Coherent breathing at ~5.5 bpm',
 'The "resonance frequency" that maxes HRV',
 'Slow rhythmic breathing at roughly 5.5 breaths per minute (5.5 s in / 5.5 s out) hits the cardiovascular resonance frequency, dramatically increasing heart-rate variability (HRV) — a marker of autonomic flexibility and resilience.',
 'promising', 4,
 '{"duration":"5–20 min","intensity":"5.5 s in / 5.5 s out, gentle nasal breathing","frequency":"daily","prerequisites":"none"}'::jsonb,
 ARRAY['Acute increase in HRV (often 2–3× baseline)','Lower blood pressure with 8+ weeks of regular practice','Improved emotional regulation and focus','Useful for performance anxiety and panic'],
 ARRAY['Light-headedness if forced — keep it gentle','Pregnancy: shorten holds, no breath retention','Asthma sufferers: ensure exhale is unforced'],
 E'## The resonance frequency\n\nThe cardiovascular system has a natural **resonance frequency** — usually around **5.5–6.5 breaths per minute** in adults. Breathing at this rate causes blood pressure and heart rate oscillations to **synchronise constructively**, producing a maximal increase in heart-rate variability (HRV).\n\nHigher HRV → better autonomic flexibility → better stress tolerance, recovery, and emotional regulation. Athletes, special-forces operators and clinicians have all converged on this frequency as a powerful baseline practice.\n\n## The pattern\n\n```\nInhale 5.5 s\n│   │   │   │   │\n└───┴───┴───┴───┘\n        ↓\nExhale 5.5 s\n│   │   │   │   │\n└───┴───┴───┴───┘\n```\n\nNose-breathe both in and out. No holds. The breath should be smooth, soft, and quiet — if anyone could hear it, slow down.\n\n## What it does (acutely)\n\n- **Doubles or triples HRV within minutes** of starting (Lehrer & Gevirtz, 2014).\n- **Activates the baroreflex** — the system that regulates blood pressure.\n- **Shifts autonomic balance** sharply toward parasympathetic.\n\n## What it does (long-term)\n\n8+ weeks of 20 min/day:\n- **Reduced systolic BP** by 4–5 mmHg in hypertensive subjects (Joseph et al., 2005).\n- **Improved depression and anxiety scores** in clinical populations (Goessl et al., 2017 meta-analysis).\n- **Sustained baseline HRV improvement** even outside of practice.\n\n## How to do it\n\n- **Easiest entry**: download a "coherent breathing" or "resonance breathing" app (e.g. Breathwrk, Othership, or just a metronome at 5.5 bpm).\n- **Posture**: sit upright, spine relaxed, shoulders soft.\n- **Start at 5 min/day** for week one.\n- **Build to 10–20 min/day** by week 4.\n- **Best times**: morning before work, mid-afternoon dip, or wind-down before bed.\n\nIf 5.5 s feels too slow, start with 4-4 and lengthen by 0.5 s per week until you reach 5.5 or 6 s.',
 '[{"author":"Lehrer & Gevirtz","title":"Heart rate variability biofeedback: how and why does it work?","year":2014,"url":"https://pubmed.ncbi.nlm.nih.gov/25101026/"},{"author":"Joseph et al.","title":"Slow breathing and hypertension","year":2005,"url":"https://pubmed.ncbi.nlm.nih.gov/15630092/"},{"author":"Goessl et al.","title":"HRV biofeedback for stress and anxiety","year":2017,"url":"https://pubmed.ncbi.nlm.nih.gov/28478782/"}]'::jsonb,
 3),

('nervous-system','cold-face-dive-reflex',
 'Cold face: the mammalian dive reflex',
 '30 seconds to drop a panic spike',
 'Submerging your face in cold water (or holding an ice pack to forehead/cheeks) for 30–60 seconds activates the mammalian dive reflex — a hard-wired vagal response that drops heart rate within seconds and is used clinically to abort panic attacks.',
 'strong', 3,
 '{"duration":"30–60 s","intensity":"face submerged in ~10 °C water OR ice pack on forehead/cheeks while breath-holding","frequency":"on-demand for acute panic, anger, dissociation","prerequisites":"healthy heart — known arrhythmia: clear with cardiologist"}'::jsonb,
 ARRAY['Immediate parasympathetic activation (HR drops 10–25 % in seconds)','Used in DBT (TIPP skill) to abort panic, dissociation, and rage','Free, deployable anywhere with a sink','Effects last ~30 minutes after a single application'],
 ARRAY['Known cardiac arrhythmia: do not use without medical clearance','Cold sensitivity disorders: shorten exposure','Avoid if extremely cold and shivering — opposite goal'],
 E'## The reflex\n\nThe **mammalian dive reflex** is hard-wired in all air-breathing vertebrates. When the **face is exposed to cold water** (especially the forehead, eyes, and cheeks) **while breath-holding**, the body triggers:\n\n- **Bradycardia** — heart rate drops 10–25 % within seconds.\n- **Peripheral vasoconstriction** — blood shunts to vital organs.\n- **Strong parasympathetic dominance** — sympathetic "panic" signal is overridden.\n\nIt evolved to help mammals conserve oxygen during dives. The same reflex doubles as the most reliable acute parasympathetic activator known.\n\n## How to use it\n\n**Method 1: Sink dunk**\n1. Fill a sink with cold water (~10 °C, add ice if needed).\n2. Hold breath, lean forward, **submerge face from forehead to chin for 30 s**.\n3. Repeat 1–2× if needed.\n\n**Method 2: Ice pack** (for use anywhere)\n1. Hold a flexible ice pack (or cold wet cloth) **firmly across forehead, eyes and cheeks**.\n2. Hold breath while applying.\n3. **30–60 s.** Repeat 1–2× if needed.\n\n## Where it''s used clinically\n\nThe **TIPP skill** in Marsha Linehan''s **Dialectical Behaviour Therapy** uses cold face exposure as the **first line for severe emotional dysregulation, panic, and dissociation**. It works in seconds, when nothing else does.\n\nIt''s also used by emergency physicians to **terminate supraventricular tachycardia (SVT)** in healthy patients before pharmacological intervention.\n\n## When to reach for it\n\n- **Panic attack onset** — abort within 60 s.\n- **Dissociation/freeze** — pulls you back into your body.\n- **Rage spike** — buys 30 minutes of clear thinking.\n- **Cannot fall asleep due to anxious arousal** — apply once, then attempt sleep.\n\n## What it''s NOT\n\n- A cold plunge protocol — totally different mechanism (and goal).\n- A daily practice — best reserved for acute use, where the contrast is the medicine.\n- Safe for everyone — anyone with diagnosed arrhythmia or cardiac conditions should clear it with their clinician first.',
 '[{"author":"Foster & Sheel","title":"The human diving response","year":2005,"url":"https://pubmed.ncbi.nlm.nih.gov/15705636/"},{"author":"Linehan","title":"DBT Skills Training Manual","year":2014},{"author":"Schipke & Pelzer","title":"Effect of immersion, submersion and apnea on the diving response","year":2001,"url":"https://pubmed.ncbi.nlm.nih.gov/11710698/"}]'::jsonb,
 4);
